def get_arithmetic_operation():
    """Get the arithmetic operation from user input."""
    while True:
        operation = input("Enter the arithmetic operation (+, -, *, /): ").strip()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("Invalid operation. Please try again.")

def get_numbers():
    """Get two numbers from user input."""
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            return num1, num2
        except ValueError:
            print("Invalid input. Please enter numbers only.")

def perform_arithmetic(operation, num1, num2):
    """Perform the arithmetic operation on the given numbers."""
    if operation == '+':
        return num1 + num2
    elif operation == '-':
        return num1 - num2
    elif operation == '*':
        return num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        return num1 / num2
    else:
        raise ValueError("Invalid operation.")

def main():
    """Run the program and perform the arithmetic operation."""
    operation = get_arithmetic_operation()
    num1, num2 = get_numbers()

    try:
        result = perform_arithmetic(operation, num1, num2)
        print(f"{num1} {operation} {num2} = {result}")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
